// Drop-in replacement for ios/App/App/AppDelegate.swift (generated by `npx cap add ios`).
// Paste these contents over the generated file — do not add this file to Xcode separately.
import UIKit
import Capacitor
import MSAL

@main
class AppDelegate: UIResponder, UIApplicationDelegate {

    var window: UIWindow?

    func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        // Reattach to uploads queued in earlier runs so their results are delivered.
        BackgroundUploader.shared.start()
        return true
    }

    // iOS relaunches the app in the background when queued uploads finish.
    func application(_ application: UIApplication,
                     handleEventsForBackgroundURLSession identifier: String,
                     completionHandler: @escaping () -> Void) {
        if identifier == BackgroundUploader.sessionId {
            BackgroundUploader.shared.backgroundCompletionHandler = completionHandler
            BackgroundUploader.shared.start()
        } else {
            completionHandler()
        }
    }

    func application(_ app: UIApplication, open url: URL, options: [UIApplication.OpenURLOptionsKey: Any] = [:]) -> Bool {
        // Returns the user to the app after the Microsoft sign-in sheet.
        if MSALPublicClientApplication.handleMSALResponse(url, sourceApplication: options[.sourceApplication] as? String) {
            return true
        }
        return ApplicationDelegateProxy.shared.application(app, open: url, options: options)
    }

    func application(_ application: UIApplication, continue userActivity: NSUserActivity, restorationHandler: @escaping ([UIUserActivityRestoring]?) -> Void) -> Bool {
        return ApplicationDelegateProxy.shared.application(application, continue: userActivity, restorationHandler: restorationHandler)
    }
}
